"""1420 (#11 enemy_body_size_variants): Record-MissionCoverage-v1416.ps1 with a 'takedown' case on the mission map. Every
paired takedown so far was on the Dunwall tutorial guards (guard_male_small); Edge of the World also has tall men
(overseer_male_tall, elite_male_tall) and women (elite_female, the civilians), whose native takedown scenes are their own.
The case finds the NPC of -TargetSpawner on the map (its root and facing from the world NPC catalog), places the source
0.9 m behind it facing its back, holds the free camera 3 m to the side of the pair at chest height, and chokes (RB held
6.5 s) or kills (RT) it with -TakedownKind; the input runs beside the sampling. It passes when the source ran a native
takedown (Assassination 13 or Choke 41) and the target ends unconscious (choke) or dead (lethal) in both worlds.
Generated by make_mission_coverage_v1420.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-MissionCoverage-v1416.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)

rep("[switch]$CounterOnParry,[double]$BlockYawOffset=0)",
    "[switch]$CounterOnParry,[double]$BlockYawOffset=0,[string]$TargetSpawner='script_spawner_docks_photograph',[ValidateSet('choke','lethal')][string]$TakedownKind='choke')")
first = s.index('\n') + 1
s = s[:first] + "# 1420 (#11): 'takedown' chokes or kills a chosen mission NPC from behind, filmed from the side. Generated by make_mission_coverage_v1420.py.\n" + s[first:]
case = r"""    if($case-eq'takedown'){
     C $source 'coop_player_health_hold on';C $peer 'coop_player_health_hold on'
     $tg=@(Living $source|Where-Object {$_.spawnerName-eq$TargetSpawner-and$_.unique})
     if(!$tg.Count){throw "Target $TargetSpawner is not on the map"}
     $np=$tg[0].position;$o=$tg[0].orientation;$fx=[double]$o[0];$fy=[double]$o[1];$fl=[Math]::Max(.1,[Math]::Sqrt($fx*$fx+$fy*$fy));$fx/=$fl;$fy/=$fl
     $row.target=[ordered]@{spawner=$TargetSpawner;definition=$tg[0].definition;position=$np;forward=@($fx,$fy)};$row.kind=$TakedownKind
     $sx=[double]$np[0]-0.9*$fx;$sy=[double]$np[1]-0.9*$fy;$sz=[double]$np[2];$syaw=[Math]::Atan2($fy,$fx)*180/[Math]::PI
     $mx=[double]$np[0]-0.45*$fx;$my=[double]$np[1]-0.45*$fy;$hcx=$mx-3.0*$fy;$hcy=$my+3.0*$fx;$hcz=$sz+1.6;$hyaw=[Math]::Atan2($my-$hcy,$mx-$hcx)*180/[Math]::PI
     C $peer (P $spawn[$peer].x $spawn[$peer].y ($spawn[$peer].z+1.7) $hyaw);Start-Sleep -Milliseconds 500;try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $peer -Pitch 8 -Quick|Out-Null}catch{}
     C $peer ('coop_observer_camera hold_at {0} {1} {2}' -f $hcx.ToString('F3',$inv),$hcy.ToString('F3',$inv),$hcz.ToString('F3',$inv));Start-Sleep -Milliseconds 400;$row.camera=@($hcx,$hcy,$hcz)
     C $source (P $sx $sy ($sz+1.7) $syaw);Start-Sleep -Milliseconds 700;$row.sourceStart=(Q $source '--player').candidatePosition
     $caps=Capture $key 14;$samples=[Collections.Generic.List[object]]::new();$active=[Collections.Generic.List[object]]::new();$watch=[Diagnostics.Stopwatch]::StartNew();$acted=$null
     $midnight=Start-Process "$lab/bin/d2_runtime_probe.exe" -ArgumentList @([string]$pids[$source],'--watch-midnight','11000') -WindowStyle Hidden -RedirectStandardOutput "$out/$key-midnight.ndjson" -RedirectStandardError "$out/$key-midnight.err" -PassThru
     while($watch.ElapsedMilliseconds-lt12000){$t=$watch.ElapsedMilliseconds
      if(!$acted-and$t-ge700){$inputArgs=if($TakedownKind-eq'choke'){@('-Button','RightShoulder','-DurationMs','6500')}else{@('-RightTrigger','255','-DurationMs','200')}
       $acted=Start-Process (Get-Process -Id $PID).Path -ArgumentList (@('-NoProfile','-File',"$lab/Send-D2Input.ps1",'-Role',$source)+$inputArgs) -WindowStyle Hidden -PassThru;$row.actedAt=$t}
      $ps=try{@((Q $source '--player-states').active|ForEach-Object {$_.id})}catch{$null};$active.Add([pscustomobject]@{ms=$t;active=$ps})
      $x=Sample $t;$samples.Add($x);Start-Sleep -Milliseconds 80}
     if($acted){try{$acted.WaitForExit(8000)|Out-Null}catch{}};if($midnight){try{$midnight.WaitForExit(3000)|Out-Null}catch{}}
     Save "$out/$key-samples.json" @($samples);Save "$out/$key-source-active.json" @($active)
     $ow=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 500;$row.outcome=[ordered]@{host=(Outcome host $TargetSpawner);client=(Outcome client $TargetSpawner)}}while($row.outcome.host-ne$row.outcome.client-and$ow.ElapsedMilliseconds-lt8000)
     $row.sourceStates=@($active|ForEach-Object {$_.active}|Where-Object {$null-ne$_}|ForEach-Object {[int]$_}|Sort-Object -Unique)
     C $source 'coop_player_health_hold off';C $peer 'coop_player_health_hold off'
     $expected=if($TakedownKind-eq'choke'){'unconscious'}else{'dead'}
     if(!@($row.sourceStates|Where-Object {$_-eq13-or$_-eq41}).Count){throw "No native takedown on the source (states $($row.sourceStates-join ','))"}
     if($row.outcome.host-ne$expected-or$row.outcome.client-ne$expected){throw "Target outcome host $($row.outcome.host), client $($row.outcome.client), expected $expected"}
     $row.checks.Add("Native $TakedownKind of $($tg[0].definition): source states $($row.sourceStates-join ','); $expected in both worlds")}
"""
rep("    if($case-eq'shop'){\n", case + "    if($case-eq'shop'){\n")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-MissionCoverage-v1420.ps1').write_bytes(out.encode('utf-8'))
print('ok')
